package in.aicon.pocket;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class RepaymentReviewTest {
 SQLiteDatabase db;LedgerSyncStore store;String subject="1234567890",loan=UUID.randomUUID().toString(),left=UUID.randomUUID().toString(),right=UUID.randomUUID().toString();
 @Before public void setup()throws Exception{Context c=RuntimeEnvironment.getApplication();c.deleteDatabase(AccountScope.databaseFor(subject));db=c.openOrCreateDatabase(AccountScope.databaseFor(subject),0,null);store=new LedgerSyncStore(db,subject);ContentValues v=new ContentValues();v.put("uuid",loan);v.put("kind","lent");v.put("amount",50000);v.put("day","2026-11-11");v.put("account","Cash");v.put("dest","");v.put("category","Debt");v.put("note","");v.put("person","Sample");v.put("loan","");db.insertOrThrow("tx",null,v);db.beginTransaction();try{store.captureLocalEdits();db.setTransactionSuccessful();}finally{db.endTransaction();}}
 @After public void close(){db.close();}
 Map<String,SyncModel.Record> invalid()throws Exception{Map<String,SyncModel.Record> records=new TreeMap<>(store.snapshot().records);for(String id:new String[]{left,right})records.put(id,new SyncModel.Record(id,LedgerWire.transaction(id,"repay_in",30000,"2026-11-11","Cash","","Debt",id.equals(left)?"Device A payment":"Device B payment","Sample",loan).toString(),false,Collections.singletonMap(id.equals(left)?"device_a":"device_b",1L)));return records;}
 void stage(Map<String,SyncModel.Record> records)throws Exception{try{LedgerWire.validate(records);fail();}catch(LedgerIntegrity.RepaymentConflict issue){store.retainRepayment(store.snapshot().revision,records,issue);}}
 long count(){try(Cursor c=db.rawQuery("SELECT count(*) FROM tx",null)){c.moveToFirst();return c.getLong(0);}}
 @Test public void invalidCombinedRepaymentsStageWithoutChangingMoneyThenExplicitDeletionCommits()throws Exception{Map<String,SyncModel.Record> candidates=invalid();long revision=store.snapshot().revision;int pending=store.pending().size();stage(candidates);RepaymentReviewStore.Review review=store.repaymentReview();assertEquals(loan,review.issue.loanId);assertEquals(60000,review.issue.total);assertEquals(50000,review.issue.principal);assertEquals(1,count());assertEquals(revision,store.snapshot().revision);assertEquals(pending,store.pending().size());assertTrue(store.removeReviewedRepayment(review.key,revision,left));assertNull(store.repaymentReview());assertEquals(2,count());assertTrue(store.snapshot().records.get(left).deleted);assertNull(store.snapshot().records.get(left).payload);assertFalse(store.snapshot().records.get(right).deleted);assertEquals(-1,SyncModel.compare(candidates.get(left).clock,store.snapshot().records.get(left).clock));assertEquals(loan,new JSONObject(store.snapshot().records.get(right).payload).getString("loan"));}
 @Test public void staleOrNonPaymentChoicesCannotRemovePrincipal()throws Exception{stage(invalid());RepaymentReviewStore.Review review=store.repaymentReview();try{store.removeReviewedRepayment(review.key,review.revision,loan);fail();}catch(IllegalArgumentException expected){}try{store.removeReviewedRepayment(UUID.randomUUID().toString(),review.revision,left);fail();}catch(IllegalStateException expected){}ContentValues v=new ContentValues();v.put("note","New local note");db.update("tx",v,"uuid=?",new String[]{loan});db.beginTransaction();try{store.captureLocalEdits();db.setTransactionSuccessful();}finally{db.endTransaction();}try{store.removeReviewedRepayment(review.key,review.revision,left);fail();}catch(IllegalStateException expected){}assertEquals(1,count());assertNotNull(store.repaymentReview());}
 @Test public void severalOverpaidDebtsKeepEveryChoiceStagedUntilWholeLedgerIsValid()throws Exception{Map<String,SyncModel.Record> records=invalid();String second=UUID.randomUUID().toString(),x=UUID.randomUUID().toString(),y=UUID.randomUUID().toString();records.put(second,new SyncModel.Record(second,LedgerWire.transaction(second,"lent",50000,"2026-11-11","Cash","","Debt","Second","Sample","").toString(),false,Collections.singletonMap("other",1L)));for(String id:new String[]{x,y})records.put(id,new SyncModel.Record(id,LedgerWire.transaction(id,"repay_in",30000,"2026-11-11","Cash","","Debt","Second payment","Sample",second).toString(),false,Collections.singletonMap("other",1L)));stage(records);RepaymentReviewStore.Review first=store.repaymentReview();String removed=first.issue.repayments.get(0);assertFalse(store.removeReviewedRepayment(first.key,first.revision,removed));assertEquals(1,count());assertEquals(first.revision,store.snapshot().revision);RepaymentReviewStore.Review next=store.repaymentReview();assertNotEquals(first.key,next.key);try{store.removeReviewedRepayment(first.key,first.revision,removed);fail();}catch(IllegalStateException expected){}assertTrue(store.removeReviewedRepayment(next.key,next.revision,next.issue.repayments.get(0)));assertEquals(4,count());assertTrue(store.snapshot().records.get(removed).deleted);}
 @Test public void syncEngineRetainsInvalidMergedCandidateBeforeAnyUploadOrMoneyReplacement()throws Exception{Map<String,SyncModel.Record> records=invalid();List<SyncEngine.RemoteOperation> operations=new ArrayList<>();for(SyncModel.Record r:records.values())operations.add(new SyncEngine.RemoteOperation("file_"+operations.size(),UUID.randomUUID().toString(),r));SyncEngine.Remote remote=new SyncEngine.Remote(){public List<SyncEngine.RemoteOperation> pull(){return operations;}public String reserveFileId(){fail();return null;}public void append(SyncEngine.Pending p){fail();}public void deleteContentFile(String id){fail();}};long revision=store.snapshot().revision;try{new SyncEngine(store,remote,()->{},LedgerWire::validate).sync();fail();}catch(LedgerIntegrity.RepaymentConflict expected){}assertNotNull(store.repaymentReview());assertEquals(revision,store.snapshot().revision);assertEquals(1,count());}

}
